const settings = $input.first().json;
const industries = String(settings.industries || '')
  .split(',')
  .map((industry) => industry.trim())
  .filter(Boolean);

if (industries.length === 0) {
  throw new Error('Supply risk settings has no industries. Put at least one industry in industries, separated by commas.');
}

return industries.map((industry) => ({
  json: {
    industry,
    regions: settings.regions,
    lookbackDays: settings.lookbackDays,
    articleCount: settings.articleCount,
  },
}));

parameters.text:
=You are tracking physical supply-chain disruptions for one industry: {{ $json.industry }}

Call the Webz.io news search tool exactly once, with these arguments:

- query: disaster earthquake flood storm fire explosion port closure strike power outage affecting {{ $json.industry }} supply chain {{ $json.regions }}
- days: {{ $json.lookbackDays }}
- language: ["english"]
- k: {{ $json.articleCount }}

Do not pass country, category, sentiment, or any other filter. Region names belong in the query.

From the articles, extract events that can disrupt suppliers, plants, ports, transport, power, or logistics for this industry. Include earthquakes, floods, wildfires, storms, tsunamis, volcanic eruptions, factory fires and explosions, port or airport closures, major strikes, power outages, and droughts affecting production.

Exclude earnings, market commentary, generic climate opinion, political opinion, and disasters with no plausible link to this industry's supply chain.

For each event return event, location, disruption_type, severity, supply_chain_impact, headline, publisher, occurred, and url. `supply_chain_impact` must be one sentence grounded in the article. Do not invent damage, closures, or supplier relationships. Set industry to {{ $json.industry }}.

If nothing qualifies, return an empty events array.

parameters.jsCode:
const settings = $('Supply risk settings').first().json;
const staticData = $getWorkflowStaticData('global');
const seen = new Set(Array.isArray(staticData.seenDisruptions) ? staticData.seenDisruptions : []);
const clean = (value) => String(value ?? '').replace(/[<>|]/g, '').trim();
const severityRank = { low: 1, medium: 2, high: 3 };
const minRank = severityRank[clean(settings.minSeverity).toLowerCase()] || 2;
const typeLabels = {
  earthquake: 'Earthquake', flood: 'Flood', wildfire: 'Wildfire', storm: 'Storm',
  tsunami: 'Tsunami', volcanic: 'Volcanic eruption', industrial_accident: 'Industrial accident',
  port_closure: 'Port closure', labor_action: 'Labor action', power_outage: 'Power outage',
  drought: 'Drought', other: 'Disruption',
};

const normalize = (value) => clean(value).toLowerCase().replace(/[^a-z0-9]+/g, '');
const risks = [];
const seenThisRun = new Set();
const sectionsByIndustry = {};

for (const item of $input.all()) {
  const output = item.json.output || {};
  const industry = clean(output.industry) || 'Supply chain';
  const events = Array.isArray(output.events) ? output.events : [];

  for (const event of events) {
    const name = clean(event.event);
    const location = clean(event.location);
    const url = String(event.url ?? '').trim();
    const severity = clean(event.severity).toLowerCase();
    if (!name || !location || !url) continue;
    if ((severityRank[severity] || 1) < minRank) continue;

    const key = normalize(name) + '|' + normalize(location);
    if (seen.has(key) || seenThisRun.has(key)) continue;
    seen.add(key);
    seenThisRun.add(key);

    const record = {
      industry,
      event: name,
      location,
      disruption_type: event.disruption_type || 'other',
      severity,
      supply_chain_impact: clean(event.supply_chain_impact),
      headline: clean(event.headline) || name,
      publisher: clean(event.publisher),
      occurred: clean(event.occurred),
      url,
    };
    risks.push(record);

    const label = typeLabels[record.disruption_type] || record.disruption_type;
    let line = '• *' + name + '* — ' + location + ', ' + label + ', ' + severity;
    if (record.supply_chain_impact) line += '\n  ' + record.supply_chain_impact;
    line += ' — <' + url + '|' + record.headline + '>';
    if (record.publisher) line += ' (' + record.publisher + ')';
    if (!sectionsByIndustry[industry]) sectionsByIndustry[industry] = [];
    sectionsByIndustry[industry].push(line);
  }
}

staticData.seenDisruptions = Array.from(seen).slice(-1000);
const sections = Object.entries(sectionsByIndustry).map(([industry, lines]) => '*' + industry + '*\n' + lines.join('\n'));

return [{
  json: {
    hasNew: risks.length > 0,
    risks,
    alertText: ':warning: *Supply-chain risk alert*\n\n' + sections.join('\n\n'),
    slackChannel: settings.slackChannel,
  },
}];

const foundAt = new Date().toISOString();
const risks = Array.isArray($input.first().json.risks) ? $input.first().json.risks : [];

return risks.map((risk) => ({
  json: {
    found_at: foundAt,
    industry: risk.industry,
    event: risk.event,
    location: risk.location,
    disruption_type: risk.disruption_type,
    severity: risk.severity,
    supply_chain_impact: risk.supply_chain_impact,
    headline: risk.headline,
    publisher: risk.publisher,
    occurred: risk.occurred,
    url: risk.url,
  },
}));
